// Package contracts owns the JSON Schema contracts generated from the existing
// Zod definitions and the Go representation of those validated documents.
//
// The JSON files under schemas/ are generated by generate_schemas.mjs and are
// embedded at build time, so validation never needs Node.js or the TypeScript
// sources at runtime. JSON Schema cannot express a few Zod refinements; those
// cross-field rules are implemented here and applied together with the
// structural schema.
package contracts

import (
	"bytes"
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"net/url"
	"path"
	"strings"
	"unicode/utf16"

	"github.com/santhosh-tekuri/jsonschema/v6"
)

// Name identifies one embedded contract.
type Name string

const (
	NameAPIConfig             Name = "api-config"
	NameAPICredentials        Name = "api-credentials"
	NameAnalyzeRequest        Name = "analyze-request"
	NameConnectionTestRequest Name = "connection-test-request"
	NameModelsRequest         Name = "models-request"
	NameDimensionOne          Name = "dimension-one"
	NameDimensionTwo          Name = "dimension-two"
	NameDimensionThree        Name = "dimension-three"
	NameDraft                 Name = "draft"
	NameGrade                 Name = "grade"
	NameGradeRequest          Name = "grade-request"
	NameQuizHintsOutput       Name = "quiz-hints-output"
	NameQuizHintsRequest      Name = "quiz-hints-request"
	NameQuizQuestion          Name = "quiz-question"
	NameExportRequest         Name = "export-request"
)

//go:generate node generate_schemas.mjs

//go:embed schemas/*.json
var schemaFiles embed.FS

// Schema is one compiled JSON Schema contract.
type Schema struct {
	name     Name
	document any
	compiled *jsonschema.Schema
}

var schemas = loadSchemas()

func loadSchemas() map[Name]*Schema {
	entries, err := fs.Glob(schemaFiles, "schemas/*.json")
	if err != nil {
		panic(fmt.Sprintf("contracts: list embedded schemas: %v", err))
	}
	loaded := make(map[Name]*Schema, len(entries))
	for _, entry := range entries {
		name := Name(strings.TrimSuffix(path.Base(entry), ".json"))
		data, err := schemaFiles.ReadFile(entry)
		if err != nil {
			panic(fmt.Sprintf("contracts: read %s: %v", entry, err))
		}
		loaded[name] = compileSchema(name, data)
	}
	if len(loaded) == 0 {
		panic("contracts: no embedded schemas")
	}
	return loaded
}

func compileSchema(name Name, data []byte) *Schema {
	var document any
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	if err := decoder.Decode(&document); err != nil {
		panic(fmt.Sprintf("contracts: decode %s: %v", name, err))
	}

	location := "https://contracts.lexigene.invalid/" + string(name) + ".json"
	compiler := jsonschema.NewCompiler()
	if err := compiler.AddResource(location, document); err != nil {
		panic(fmt.Sprintf("contracts: add %s: %v", name, err))
	}
	compiled, err := compiler.Compile(location)
	if err != nil {
		panic(fmt.Sprintf("contracts: compile %s: %v", name, err))
	}
	return &Schema{name: name, document: document, compiled: compiled}
}

// Lookup returns the compiled contract with the given name.
func Lookup(name Name) *Schema {
	schema, ok := schemas[name]
	if !ok {
		panic(fmt.Sprintf("contracts: unknown schema %q", name))
	}
	return schema
}

// Name returns the contract name.
func (s *Schema) Name() Name { return s.name }

// Document returns the JSON Schema document used for prompting. Callers must
// treat the returned value as read-only.
func (s *Schema) Document() any { return s.document }

// Issue is one structural or cross-field contract violation. Path is a dot
// path; it is empty for a violation at the document root.
type Issue struct {
	Path    string
	Message string
}

// Issues returns every structural and cross-field violation for value. An
// empty result means the value satisfies the contract.
func (s *Schema) Issues(value any) []Issue {
	issues := make([]Issue, 0, 4)

	if err := s.compiled.Validate(value); err != nil {
		var validationError *jsonschema.ValidationError
		if errors.As(err, &validationError) {
			issues = append(issues, schemaIssues(validationError)...)
		} else {
			issues = append(issues, Issue{Message: err.Error()})
		}
	}

	issues = append(issues, refinementIssues(s.name, value)...)
	return issues
}

// Validate returns the issues as bounded human-readable strings for repair
// prompts. An empty result means the value satisfies the contract.
func (s *Schema) Validate(value any) []string {
	issues := s.Issues(value)
	if len(issues) > maxIssues {
		issues = issues[:maxIssues]
	}
	formatted := make([]string, 0, len(issues))
	for _, issue := range issues {
		path := issue.Path
		if path == "" {
			path = "(root)"
		}
		formatted = append(formatted, path+": "+issue.Message)
	}
	return formatted
}

// maxIssues keeps repair prompts bounded, mirroring the old Zod issue slice.
const maxIssues = 8

func schemaIssues(validationError *jsonschema.ValidationError) []Issue {
	var units []jsonschema.OutputUnit
	flattenOutput(*validationError.BasicOutput(), &units)

	issues := make([]Issue, 0, len(units))
	for _, unit := range units {
		if unit.Error == nil {
			continue
		}
		issues = append(issues, Issue{
			Path:    pointerPath(unit.InstanceLocation),
			Message: unit.Error.String(),
		})
	}
	if len(issues) == 0 {
		return []Issue{{Message: validationError.Error()}}
	}
	return issues
}

func flattenOutput(unit jsonschema.OutputUnit, out *[]jsonschema.OutputUnit) {
	if unit.Error != nil {
		*out = append(*out, unit)
	}
	for _, child := range unit.Errors {
		flattenOutput(child, out)
	}
}

func pointerPath(pointer string) string {
	if pointer == "" {
		return ""
	}
	segments := strings.Split(strings.TrimPrefix(pointer, "/"), "/")
	for index, segment := range segments {
		segment = strings.ReplaceAll(segment, "~1", "/")
		segments[index] = strings.ReplaceAll(segment, "~0", "~")
	}
	return strings.Join(segments, ".")
}

// refinementIssues implements the Zod refinements that JSON Schema cannot
// express: provider URL scheme, unique register levels, unique dialogue
// settings and unique quiz ids.
func refinementIssues(name Name, value any) []Issue {
	var issues []Issue

	checkConfig := func(value any, prefix string) {
		object, ok := value.(map[string]any)
		if !ok {
			return
		}
		baseURL, ok := object["baseUrl"].(string)
		if !ok {
			return
		}
		parsed, err := url.Parse(baseURL)
		if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" {
			issues = append(issues, Issue{Path: prefix + "baseUrl", Message: "Use HTTP or HTTPS"})
		}
	}
	checkDraft := func(value any, prefix string) {
		object, ok := value.(map[string]any)
		if !ok {
			return
		}
		dimensions, ok := object["dimensions"].(map[string]any)
		if !ok {
			return
		}
		if three, ok := dimensions["three"]; ok {
			issues = append(issues, dimensionThreeRefinements(three, prefix+"dimensions.three.")...)
		}
	}
	field := func(value any, key string) (any, bool) {
		object, ok := value.(map[string]any)
		if !ok {
			return nil, false
		}
		field, ok := object[key]
		return field, ok
	}

	switch name {
	case NameAPIConfig, NameAPICredentials:
		checkConfig(value, "")
	case NameConnectionTestRequest, NameModelsRequest, NameGradeRequest, NameQuizHintsRequest:
		if config, ok := field(value, "config"); ok {
			checkConfig(config, "config.")
		}
	case NameAnalyzeRequest:
		if config, ok := field(value, "config"); ok {
			checkConfig(config, "config.")
		}
		if draft, ok := field(value, "draft"); ok {
			checkDraft(draft, "draft.")
		}
	case NameDraft:
		checkDraft(value, "")
	case NameDimensionThree:
		issues = append(issues, dimensionThreeRefinements(value, "")...)
	case NameExportRequest:
		issues = append(issues, exportRefinements(value)...)
	}

	return issues
}

func dimensionThreeRefinements(value any, prefix string) []Issue {
	object, ok := value.(map[string]any)
	if !ok {
		return nil
	}
	var issues []Issue

	if register, ok := object["register"].(map[string]any); ok {
		if levels, ok := register["levels"].([]any); ok {
			seen := make(map[int64]bool, len(levels))
			valid := len(levels) == 10
			for _, item := range levels {
				level, ok := item.(map[string]any)
				if !ok {
					continue
				}
				number, ok := integerValue(level["level"])
				if !ok {
					continue
				}
				seen[number] = true
			}
			if !valid || len(seen) != 10 {
				issues = append(issues, Issue{Path: prefix + "register.levels", Message: "Levels must contain each integer from 1 to 10"})
			}
		}
	}

	if slices, ok := object["slices"].(map[string]any); ok {
		if dialogues, ok := slices["dialogues"].([]any); ok {
			settings := make(map[string]bool, len(dialogues))
			for _, item := range dialogues {
				dialogue, ok := item.(map[string]any)
				if !ok {
					continue
				}
				if setting, ok := dialogue["setting"].(string); ok {
					settings[setting] = true
				}
			}
			if len(settings) != 3 {
				issues = append(issues, Issue{Path: prefix + "slices.dialogues", Message: "Include friends, work and culture"})
			}
		}
		if quiz, ok := slices["quiz"].([]any); ok {
			ids := make(map[string]bool, len(quiz))
			for _, item := range quiz {
				question, ok := item.(map[string]any)
				if !ok {
					continue
				}
				if id, ok := question["id"].(string); ok {
					ids[id] = true
				}
			}
			if len(ids) != 2 {
				issues = append(issues, Issue{Path: prefix + "slices.quiz", Message: "Quiz IDs must be unique"})
			}
		}
	}

	return issues
}

// exportRefinements mirrors the export route's refinements: control characters
// in tags and deck names, and the total card-content cap. Lengths are measured
// in UTF-16 code units, the same unit the browser/Zod limits use.
func exportRefinements(value any) []Issue {
	object, ok := value.(map[string]any)
	if !ok {
		return nil
	}
	var issues []Issue

	if deckName, ok := object["deckName"].(string); ok {
		if hasControlCharacter(deckName) {
			issues = append(issues, Issue{Path: "deckName", Message: "Deck name contains control characters"})
		}
		if utf16Len(deckName) > 80 {
			issues = append(issues, Issue{Path: "deckName", Message: "Deck name must be at most 80 characters"})
		}
	}

	cards, ok := object["cards"].([]any)
	if !ok {
		return issues
	}

	total := 0
	for index, item := range cards {
		card, ok := item.(map[string]any)
		if !ok {
			continue
		}
		limits := []struct {
			field string
			max   int
		}{
			{"id", 2_048},
			{"front", 10_000},
			{"back", 30_000},
		}
		for _, limit := range limits {
			text, ok := card[limit.field].(string)
			if !ok {
				continue
			}
			if utf16Len(text) > limit.max {
				issues = append(issues, Issue{
					Path:    fmt.Sprintf("cards.%d.%s", index, limit.field),
					Message: fmt.Sprintf("must be at most %d characters", limit.max),
				})
			}
		}

		front, _ := card["front"].(string)
		back, _ := card["back"].(string)
		total += utf16Len(front) + utf16Len(back)

		tags, _ := card["tags"].([]any)
		for tagIndex, tag := range tags {
			text, ok := tag.(string)
			if !ok {
				continue
			}
			if hasControlCharacter(text) {
				issues = append(issues, Issue{
					Path:    fmt.Sprintf("cards.%d.tags.%d", index, tagIndex),
					Message: "Tag contains control characters",
				})
			}
			if utf16Len(text) > 64 {
				issues = append(issues, Issue{
					Path:    fmt.Sprintf("cards.%d.tags.%d", index, tagIndex),
					Message: "must be at most 64 characters",
				})
			}
		}
	}

	if total > 4_000_000 {
		issues = append(issues, Issue{Path: "cards", Message: "Card content exceeds the export size limit"})
	}
	return issues
}

func hasControlCharacter(value string) bool {
	for _, character := range value {
		if character < 0x20 || character == 0x7f {
			return true
		}
	}
	return false
}

func utf16Len(value string) int {
	return len(utf16.Encode([]rune(value)))
}

func integerValue(value any) (int64, bool) {
	switch number := value.(type) {
	case json.Number:
		parsed, err := number.Int64()
		return parsed, err == nil
	case float64:
		if number != float64(int64(number)) {
			return 0, false
		}
		return int64(number), true
	}
	return 0, false
}
